{"path": "/tmp/sv-bee0aeb5661244e3bd2a1e37eb0df5be/Components/Pages/Catalog/CatalogFilterSidebar.razor", "file_text": "<div class="p-3 border rounded bg-light">
    <h5 class="mb-3">Filters</h5>

    <div class="mb-3">
        <label class="form-label fw-semibold">Categories</label>
        @if (Categories.Any())
        {
            @foreach (var category in Categories)
            {
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                           checked="@IsSelected(category)"
                           @onchange="() => ToggleCategory(category)" />
                    <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                </div>
            }
        }
        else
        {
            <p class="text-muted small mb-0">No categories available</p>
        }
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold">Price Range</label>
        <div class="d-flex gap-2 align-items-center">
            <input type="number" class="form-control form-control-sm" placeholder="Min"
                   value="@_minPrice" @onchange="HandleMinPriceChanged" min="0" step="0.01" />
            <span>–</span>
            <input type="number" class="form-control form-control-sm" placeholder="Max"
                   value="@_maxPrice" @onchange="HandleMaxPriceChanged" min="0" step="0.01" />
        </div>
    </div>

    <div class="mb-3">
        <div class="form-check">
            <input class="form-check-input" type="checkbox" id="in-stock-only"
                   checked="@_inStockOnly"
                   @onchange="HandleInStockChanged" />
            <label class="form-check-label" for="in-stock-only">In Stock Only</label>
        </div>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary btn-sm flex-fill" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-outline-secondary btn-sm flex-fill" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnApplyFilters { get; set; }

    [Parameter]
    public EventCallback OnClearFilters { get; set; }

    private List<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category)
    {
        if (_selectedCategories.Contains(category))
            _selectedCategories.Remove(category);
        else
            _selectedCategories.Add(category);
    }

    private void HandleMinPriceChanged(ChangeEventArgs e)
    {
        _minPrice = decimal.TryParse(e.Value?.ToString(), out var val) ? val : null;
    }

    private void HandleMaxPriceChanged(ChangeEventArgs e)
    {
        _maxPrice = decimal.TryParse(e.Value?.ToString(), out var val) ? val : null;
    }

    private void HandleInStockChanged(ChangeEventArgs e)
    {
        _inStockOnly = (bool)(e.Value ?? false);
    }

    private async Task ApplyFilters()
    {
        var filter = new sv_bee0aeb5661244e3bd2a1e37eb0df5be.Services.ProductFilter(
            Categories: _selectedCategories.Any() ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnApplyFilters.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnClearFilters.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-bee0aeb5661244e3bd2a1e37eb0df5be/Components/Pages/Catalog/CatalogPage.razor", "file_text": "@page "/catalog"
@using sv_bee0aeb5661244e3bd2a1e37eb0df5be.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="RetryLoad">Retry</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-3">
            <CatalogFilterSidebar Categories="_categories"
                                  OnApplyFilters="HandleApplyFilters"
                                  OnClearFilters="HandleClearFilters" />
        </div>
        <div class="col-md-9">
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="_totalCount"
                            CurrentPage="_currentPage"
                            PageSize="PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_loading)
            {
                <div class="text-center my-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products...</p>
                </div>
            }
            else
            {
                <CatalogProductGrid Products="_products"
                                    OnProductSelected="HandleProductSelected"
                                    OnAddToCart="HandleAddToCart" />

                @if (_totalCount > 0)
                {
                    <div class="mt-3">
                        <CatalogPagination CurrentPage="_currentPage"
                                           TotalCount="_totalCount"
                                           PageSize="PageSize"
                                           OnPageChanged="HandlePageChanged" />
                    </div>
                }
            }
        </div>
    </div>
}

@code {
    private const int PageSize = 12;

    private List<Product> _products = [];
    private List<string> _categories = [];
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalCount;
    private bool _loading = true;
    private string? _error;

    /// <summary>
    /// Raised when a product card is clicked so the parent/host can navigate to a detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    /// <summary>
    /// Raised when the Add to Cart button is clicked on a product card.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            ApplyResult(productsTask.Result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            StateHasChanged();

            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        _products = result.Items;
        _totalCount = result.TotalCount;
        _currentPage = result.Page;
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleClearFilters()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }

    private async Task RetryLoad()
    {
        await LoadInitialDataAsync();
    }
}
"}

